L["Adjusts the vertical spacing between stacked nameplates. 100% = default, lower = tighter, higher = more spread."] = "Passt den vertikalen Abstand zwischen gestapelten Namensplaketten an. 100% = Standard, niedriger = enger, höher = weiter auseinander."
