L["Changing the AddOn List reskin requires a UI reload to fully swap between Blizzard and Ellesmere styles."] = "Das Ändern des Neugestaltungs Designs für die Addon Liste erfordert ein Neu Laden des UIs, um vollständig zwischen den Stilen von Blizzard und Ellesmere zu wechseln."
L["Changing the Adventure Guide reskin requires a UI reload to fully swap between Blizzard and Ellesmere styles."] = "Das Ändern des Neugestaltungs Designs für den Abenteuerführer erfordert ein Neu Laden des UIs, um vollständig zwischen den Stilen von Blizzard und Ellesmere zu wechseln."
L["Changing the Auction House reskin requires a UI reload to fully swap between Blizzard and Ellesmere styles."] = "Das Ändern des Neugestaltungs Designs für das Auktionshaus erfordert ein Neu Laden des UIs, um vollständig zwischen den Stilen von Blizzard und Ellesmere zu wechseln."
L["Changing the Calendar reskin requires a UI reload to fully swap between Blizzard and Ellesmere styles."] = "Das Ändern des Neugestaltungs Designs für den Kalender erfordert ein Neu Laden des UIs, um vollständig zwischen den Stilen von Blizzard und Ellesmere zu wechseln."
L["Changing the Catalyst reskin requires a UI reload to fully swap between Blizzard and Ellesmere styles."] = "Das Ändern des Neugestaltungs Designs für den Katalysator erfordert ein Neu Laden des UIs, um vollständig zwischen den Stilen von Blizzard und Ellesmere zu wechseln."
L["Changing the Choice Windows reskin requires a UI reload to fully swap between Blizzard and Ellesmere styles."] = "Das Ändern des Skins für Auswahlfenster erfordert ein Neuladen des UI, um vollständig zwischen dem Blizzard- und Ellesmere Stil zu wechseln."
L["Changing the Collections reskin requires a UI reload to fully swap between Blizzard and Ellesmere styles."] = "Das Ändern des Neugestaltungs Designs für Sammlungen erfordert ein Neu Laden des UIs, um vollständig zwischen den Stilen von Blizzard und Ellesmere zu wechseln."
L["Changing the Crafting Orders reskin requires a UI reload to fully swap between Blizzard and Ellesmere styles."] = "Das Ändern des Neugestaltungs Designs für Handwerksaufträge erfordert ein Neu Laden des UIs, um vollständig zwischen den Stilen von Blizzard und Ellesmere zu wechseln."
L["Changing the Delve Tier Picker reskin requires a UI reload to fully swap between Blizzard and Ellesmere styles."] = "Das Ändern des Skins für die Tiefen-Stufenauswahl erfordert ein Neuladen des UI, um vollständig zwischen dem Blizzard- und Ellesmere Stil zu wechseln."
