L["EllesmereUI Basics has been split into separate addons. Since you had Basics disabled, Minimap, Friends, and Quest Tracker have been disabled to match. A reload is required to apply this change."] = "„EllesmereUI Basics“ wurde in separate Addons aufgeteilt. Da Ihr „Basics“ deaktiviert hattet, wurden Minimap, Freunde und die Questverfolgung ebenfalls deaktiviert. Ein Neuladen ist erforderlich, um diese Änderung zu übernehmen."
L["EllesmereUI Beta Complete"] = "EllesmereUI-Beta abgeschlossen"
L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n"] = "EllesmereUI konnte diese Änderung nicht in Deinem Bearbeitungsmodus-Layout speichern, daher muss sie manuell eingestellt werden. Der Abklingzeit Manager muss währenddessen deaktiviert sein, da er Blizzards Abklingzeitanzeigen ausblendet und eine ausgeblendete Anzeige im Bearbeitungsmodus nicht ausgewählt werden kann.\n\n"
L["EllesmereUI has updated your CDM Edit Mode settings to ensure cooldown tracking works correctly.\n\nA UI reload is required for the changes to take effect."] = "EllesmereUI hat Eure Bearbeitungsmodus Einstellungen für den CDM aktualisiert, um sicherzustellen, dass die Abklingzeitenverfolgung korrekt funktioniert.\n\nEin Neuladen des Interfaces ist erforderlich, damit die Änderungen wirksam werden."
