L["For player frame, this provides a simple, mini castbar below player frame. To edit the main player cast bar, %sclick here|r"] = "Für das Spielerfenster wird hierdurch eine einfache, kleine Zauberleiste unter dem Spielerfenster bereitgestellt. Um die Hauptzauberleiste des Spielers zu bearbeiten, %shier klicken|r"
L["For player frame, this provides a simple, mini castbar below player frame. To edit the main player cast bar, |cff0cd29dclick here|r"] = "Für das Spielerfenster wird hierdurch eine einfache, kleine Zauberleiste unter dem Spielerfenster bereitgestellt. Um die Hauptzauberleiste des Spielers zu bearbeiten, |cff0cd29dhier klicken|r"
