L["Grow the bag window (more columns + taller, keeping its shape) so all of the active tab's slots are visible without scrolling. It only grows while open -- switching to a bigger tab enlarges it, smaller tabs keep the size -- and resets when you close the bags. Never smaller than your normal size."] = "Vergrößert das Taschenfenster (mehr Spalten + höher, behält die Form bei), sodass alle Plätze des aktiven Reiters ohne Scrollen sichtbar sind. Es wächst nur im geöffneten Zustand -- der Wechsel zu einem größeren Reiter vergrößert es, kleinere Reiter behalten die Größe bei -- und setzt sich beim Schließen der Taschen zurück. Niemals kleiner als Eure Standardgröße."
