L["Hide consumable items (potions, healthstone) from the bar when you have none in your bags, instead of showing them dimmed. They reappear automatically once you have the item again."] = "Blendet Verbrauchsgüter (Tränke, Gesundheitsstein) aus der Leiste aus, wenn Ihr keine mehr in Euren Taschen habt, anstatt sie gedimmt anzuzeigen. Sie erscheinen automatisch wieder, sobald Ihr den Gegenstand besitzt."
