L["Hide crafted items from the gear tile list.\nCrafted items cannot be upgraded at the Upgrade NPC."] = "Blendet hergestellte Gegenstände aus der Ausrüstungsliste aus.\nHergestellte Gegenstände können nicht beim Aufwertungs-NPC aufgewertet werden."
