L["Hide these instead of showing them"] = "Diese ausblenden, anstatt sie anzuzeigen"
L["Hide this bar completely while out of combat, even when the tracked buff/cooldown is active."] = "Diese Leiste außerhalb des Kampfes vollständig ausblenden, auch wenn der verfolgte Stärkungszauber bzw. die Abklingzeit aktiv ist."
L["Hide this bar's icon art, cooldown swipe, recharge edge and cooldown text, leaving only the charge or stack count."] = "Blendet Symbolgrafik, Abklingzeit Animation, Aufladekante und Abklingzeit-Text dieser Leiste aus, sodass nur die Aufladungs- oder Stapelanzahl übrig bleibt."
