L["How extra rows grow when the second row appears or disappears. Grow Down keeps the top row in place, Grow Up keeps the bottom row in place, Grow Centered keeps the bar centered."] = "Wie zusätzliche Reihen wachsen, wenn die zweite Reihe erscheint oder verschwindet. 'Nach unten' hält die oberste Reihe an Ort und Stelle, 'Nach oben' hält die unterste Reihe an Ort und Stelle, 'Zentriert' hält die Leiste zentriert."
L["How far along the arc a nest may spread its entries. Contained keeps it clear of the next nest either side, so two of them are never drawn on top of one another. Overflowing lets it use the whole of Max Nest Span."] = "Wie weit sich ein Untermenü entlang des Bogens erstrecken darf. 'Begrenzt' hält Abstand zum nächsten Untermenü auf beiden Seiten, sodass zwei niemals übereinander gezeichnet werden. 'Überschreitend' erlaubt die Nutzung des gesamten maximalen Untermenü-Bereichs."
L["How far along the arc a nest may spread its entries."] = "Wie weit sich ein Untermenü entlang des Bogens erstrecken darf."
L["How many entries a row of the grid holds. 1 stacks them into a single column; %1$s -- the most slots an action menu can hold -- lays them out in a single row."] = "Wie viele Einträge eine Zeile des Rasters enthält. Bei 1 werden sie in einer einzigen Spalte untereinander gestapelt; %1$s – die maximale Anzahl an Plätzen für ein Aktionsmenü – ordnet sie in einer einzigen Reihe an."
L["How many icons to show on the base row (the row that fills first and that Row Growth keeps in place). The rest go on the second row."] = "Wie viele Symbole in der Basisreihe angezeigt werden sollen (die Reihe, die zuerst gefüllt wird und die durch Reihenwachstum an Ort und Stelle bleibt). Der Rest kommt in die zweite Reihe."
L["How much is trimmed from the icon's top and bottom, as a percentage per side. 10% is the classic cropped look."] = "Gibt an, wie viel oben und unten vom Symbol abgeschnitten wird (als Prozentwert pro Seite). 10 % entspricht dem klassischen zugeschnittenen Look."
L["How precise the coordinates read. More decimals make the block wider."] = "Wie präzise die Koordinaten angezeigt werden. Mehr Dezimalstellen machen den Block breiter."
L["How wide the block stays, whatever the zone is called."] = "Wie breit der Block bleibt, unabhängig davon, wie die Zone heißt."
