L["In Mythic Dungeons, show consumables reminders\nwhen the remaining buff time is less than this amount"] = "In mythischen Dungeons eine Erinnerung für Verbrauchsgüter anzeigen,\nwenn die verbleibende Buff-Zeit geringer als dieser Wert ist"
