L["Only show the GCD bar for instant-cast abilities. While hard-casting or channeling a spell, the bar stays hidden (the cast bar already shows that progress)."] = "GCD Leiste nur für Spontanzauber anzeigen. Während eines Zaubers oder einer Kanalisierung bleibt die Leiste ausgeblendet (die Zauberleiste zeigt diesen Fortschritt bereits an)."
