L["Only show this bar while the tracked buff/cooldown is active. Turn off to keep an empty bar on screen at all times."] = "Diese Leiste nur anzeigen, wenn der verfolgte Stärkungszauber/Abklingzeit aktiv ist. Deaktivieren, um dauerhaft eine leere Leiste auf dem Bildschirm zu behalten."
L["Only show this bar while the tracked buff/cooldown is active. Unchecked keeps an empty bar on screen at all times."] = "Zeigt diese Leiste nur an, solange der verfolgte Stärkungszauber/die Abklingzeit aktiv ist. Deaktivieren, um jederzeit eine leere Leiste auf dem Bildschirm zu behalten."
