L["Replaces the class resource bar with an Ignore Pain tracker: the fill shows your current absorb amount scaled against your maximum health, and the bar text shows the absorb value."] = "Ersetzt die Klassenressourcenleiste durch eine Schmerz-ignorieren Anzeige: Die Füllung zeigt Ihre aktuelle Absorption im Verhältnis zu Ihrer maximalen Gesundheit an, und der Text zeigt den Absorptionswert."
L["Replaces the class resource bar with an Ironfur tracker. Each Ironfur cast adds a hash line that slides from right to left as its buff decays. Duration is talent-aware (Ursoc's Endurance and Guardian of Elune)."] = "Ersetzt die Klassenressourcenleiste durch eine Eisenfell Anzeige. Jedes Wirken von Eisenfell fügt eine Teilungslinie hinzu, die von rechts nach links gleitet, während der Stärkungszauber abläuft. Die Dauer berücksichtigt Talente (Ursocs Ausdauer und Wächter von Elune)."
