L["Scales the size of Blizzard's default game text (menus, tooltips, quest log, and more). Requires a UI reload."] = "Skaliert die Größe von Blizzards Standard Spieltexten (Menüs, Tooltips, Questlog und mehr). Erfordert ein Neuladen des UI."
L["Scales the tracking blips drawn on the map (herbs, ore, quest dots). The map itself keeps its size; other minimap elements are unaffected."] = "Skaliert die Aufspürungs Symbole auf der Karte (Kräuter, Erz, Questpunkte). Die Karte selbst behält ihre Größe bei; andere Minimap-Elemente bleiben unberührt."
