L["Sets the accent color used across all EllesmereUI elements (tabs, glows, highlights, borders). Defaults to your theme color."] = "Legt die Akzentfarbe fest, die für alle EllesmereUI-Elemente verwendet wird (Tabs, Leuchten, Hervorhebungen, Rahmen). Standard ist Ihre Themendesign Farbe."
L["Sets the font for the names that float above players, NPCs and enemies in the world.\n\nSeparate from Global Font - changing this does not affect the rest of the UI, and Global Font does not affect it.\n\nBlizzard Default leaves the name text completely untouched.\n\n|cffff4d4dRequires a re-log or restart of WoW to take effect.|r"] = "Legt die Schriftart für die Namen fest, die über Spielern, NPCs und Gegnern in der Welt schweben.\n\nGetrennt von der globalen Schriftart – das Ändern dieser Einstellung wirkt sich nicht auf das restliche UI aus, und die globale Schriftart hat keinen Einfluss darauf.\n\nBlizzard-Standard lässt den Namenstext völlig unverändert.\n\n|cffff4d4dErfordert ein Ausloggen oder einen Neustart von WoW, um wirksam zu werden.|r"
L["Sets the scale of the entire game UI. Lower values make everything smaller, higher values make everything larger."] = "Legt die Skalierung des gesamten Spiel-UIs fest. Niedrigere Werte machen alles kleiner, höhere Werte größer."
L["Sets the UI scale to the exact pixel-perfect value used by other addons. EllesmereUI does not require this to be pixel perfect."] = "Setzt die UI-Skalierung auf den exakten, Pixel-perfekten Wert, der von anderen Addons verwendet wird. EllesmereUI benötigt dies nicht zwingend."
