L["Settings are Per-Profile:|r Each profile has its own settings for this module. Click to sync and copy the current settings to all profiles."] = "Einstellungen sind profilspezifisch:|r Jedes Profil hat seine eigenen Einstellungen für dieses Modul. Klicken Sie, um zu synchronisieren und die aktuellen Einstellungen auf alle Profile zu kopieren."
