L["Show a pulsing dot on the Patch Notes button whenever EllesmereUI updates to a new version."] = "Zeigt einen pulsierenden Punkt auf der Taste für die Patch Hinweise an, wann immer die Ellesmere-Benutzeroberfläche auf eine neue Version aktualisiert wird."
L["Show a reminder when you don't have an active pet summoned. Only applies to pet classes (Hunter, Warlock, Death Knight, Mage)."] = "Zeigt eine Erinnerung an, wenn kein aktiver Begleiter herbeigerufen ist. Gilt nur für Begleiter-Klassen (Jäger, Hexenmeister, Todesritter, Magier)."
L["Show a reminder when your Demonology Warlock has the wrong pet summoned (not Felguard)."] = "Zeigt eine Erinnerung an, wenn Ihr Dämonologie-Hexenmeister den falschen Begleiter herbeigerufen hat (nicht die Teufelswache)."
L["Show a shield icon on the cast bar when an enemy's cast cannot be interrupted."] = "Zeigt ein Schildsymbol auf der Zauberleiste an, wenn der Zauber eines Feindes nicht unterbrochen werden kann."
