L["Show Spell Name"] = "Zaubernamen anzeigen"
L["Show Spell Target"] = "Zauberziel anzeigen"
L["Show Spell Tooltips on Hover"] = "Zaubertooltips beim Darüberfahren anzeigen"
L["Show Stacks"] = "Stapel anzeigen"
L["Show Still Available Column"] = "Spalte 'Noch verfügbar' anzeigen"
L["Show successful interrupt lockouts in the crowd-control icon slot."] = "Erfolgreiche Unterbrechungs-Sperren im CC-Icon-Platz anzeigen."
L["Show successful interrupt lockouts in the crowd-control icon slot.\n\nDue to addon restrictions, the duration shown is a generic 4 seconds for all classes, so it is not 100% accurate."] = "Erfolgreiche Unterbrechungs-Sperren im CC-Icon-Platz anzeigen.\n\nAufgrund von Addon-Einschränkungen beträgt die angezeigte Dauer für alle Klassen pauschal 4 Sekunden und ist daher nicht zu 100% genau."
L["Show Tanks in Extra Group"]  = "Tanks in Extra Gruppe anzeigen"
L["Show targeted spells on preview"] = "Gezielte Zauber in der Vorschau anzeigen"
L["Show Targeted Spells"]       = "Gezielte Zauber anzeigen"
L["Show Tertiary Stats"]        = "Tertiärwerte anzeigen"
L["Show Tertiary"]              = "Tertiär anzeigen"
L["Show Text"]                  = "Text anzeigen"
L["Show the bar full of its fill color while no global cooldown is running, instead of the background color."] = "Zeigt die Leiste in ihrer Füllfarbe gefüllt an, während keine globale Abklingzeit läuft, anstelle der Hintergrundfarbe."
L["Show the charge and stack counters on this bar's icons."] = "Zeigt die Aufladungs- und Stapelzähler auf den Symbolen dieser Leiste an."
L["Show the crafted quality rank on tracked items, matching the rank icon on the action bars. Items with no crafted quality are unaffected."] = "Zeigt den Herstellungsqualitätsrang bei verfolgten Gegenständen an, passend zum Rangsymbol auf den Aktionsleisten. Gegenstände ohne Herstellungsqualität sind nicht betroffen."
L["Show the expansion landing page (Omnium Folio) button at the bottom-left of the minimap. Use the cog to nudge its position."] = "Zeigt die Taste für die Erweiterungs-Startseite (Omniumfoliant) unten links auf der Minimap an. Nutzen Sie das Zahnrad, um die Position anzupassen."
L["Show the expansion landing page (Omnium Folio) button on the minimap. Use the cog to choose its corner and nudge its position."] = "Zeigt die Taste für die Erweiterungs-Startseite (Omnium-Folio) auf der Minimap an. Nutzen Sie das Zahnrad, um die Ecke auszuwählen und die Position anzupassen."
L["Show the FocusKick bar on your current target's nameplate instead of your focus target's nameplate."] = "Zeigt die FocusKick-Leiste auf der Namensplakette Ihres aktuellen Ziels anstelle Ihres Fokus-Ziels an."
L["Show the game's spell tooltip when you hover a spell in a breakdown window."] = "Zeigt den standardmäßigen Zauber-Tooltip des Spiels an, wenn Sie in einem Aufschlüsselungsfenster über einen Zauber fahren."
L["Show the leader/assistant icon while you are in combat. Disable to hide it during combat."] = "Zeigt das Schlachtzugsleiter-/Assistenten-Symbol im Kampf an. Deaktivieren, um es während des Kampfes auszublenden."
L["Show the main frames' hover highlight border on this frame. Turn off so this frame never recolors on mouseover. No effect when Highlight is off in the main frames' Hover Borders."] = "Zeigt den Hover-Hervorhebungsrahmen der Hauptfenster auf diesem Fenster an. Deaktivieren, damit sich dieses Fenster beim Mouseover nie verfärbt."
L["Show the name of who the boss is casting on."] = "Zeigt den Namen des Spielers an, auf den der Boss gerade zaubert."
L["Show the part of an absorb that exceeds your empty health and backfills over your current health. When off, absorbs only fill the empty part of the health bar."] = "Zeigt den Teil einer Absorption an, der Ihre fehlende Gesundheit übersteigt, und füllt ihn über Ihrer aktuellen Gesundheit auf. Wenn deaktiviert, füllen Absorptionen nur den leeren Teil der Gesundheitsleiste."
L["Show the part of an absorb that exceeds your empty health and backfills over your current health. When off, absorbs only fill the empty part of the health bar; on Default Blizz Frames the glow line stays pinned at the right edge."] = "Zeigt den Teil einer Absorption an, der Ihre fehlende Gesundheit übersteigt, und füllt ihn über Ihrer aktuellen Gesundheit auf. Wenn deaktiviert, füllen Absorptionen nur den leeren Teil der Leiste; bei Standard-Blizzard-Fenstern bleibt die Leuchtlinie am rechten Rand verankert."
L["Show the pet frame whenever you have a pet, ignoring the Player frame's visibility settings."] = "Zeigt das Begleiterfenster immer an, wenn Du einen Begleiter hast, und ignoriert die Sichtbarkeitseinstellungen des Spielerfensters."
L["Show the Pinned Items category in the sidebar and content grid."] = "Die Kategorie für angepinnte Gegenstände in der Seitenleiste und im Inhaltsraster anzeigen."
L["Show the player's title or guild in a smaller line below their name on friendly nameplates."] = "Zeigt den Titel oder die Gilde des Spielers in einer kleineren Zeile unter seinem Namen auf freundlichen Namensplaketten an."
L["Show the Recent Items category in the sidebar and content grid for newly acquired items."] = "Die Kategorie für aktuelle Gegenstände für neu erhaltene Gegenstände in der Seitenleiste und im Inhaltsraster anzeigen."
L["Show the recharge countdown on charge spells while a charge is still banked. When off, the recharge timer only appears at 0 charges (Blizzard default)."] = "Zeigt den Auflade-Countdown bei Auflade Zaubern an, während noch eine Aufladung verfügbar ist. Wenn deaktiviert, erscheint der Timer erst bei 0 Aufladungen (Blizzard-Standard)."
L["Show the rotating cooldown edge on every cooldown in this bar, not just while a charge is recharging. Hide Recharge Edge still overrides this for individual charge spells."] = "Zeigt die rotierende Abklingzeitkante bei jeder Abklingzeit in dieser Leiste an, nicht nur während eine Aufladung auflädt. 'Aufladekante ausblenden' überschreibt dies weiterhin für einzelne Aufladezauber."
L["Show the seasonal Earned / Cap column in the crest table."] = "Die saisonale Spalte 'Verdiener / Limit' in der Wappentabelle anzeigen."
L["Show the selected action's name next to the selected icon."] = "Zeigt den Namen der ausgewählten Aktion neben dem ausgewählten Symbol an."
L["Show the tracker as the Rebirth icon or as a compact text line with charges and time until the next one."] = "Zeigt den Tracker als Wiederbelebungs-Symbol oder als kompakte Textzeile mit Aufladungen und der Zeit bis zur nächsten an."
L["Show the unit's tooltip when hovering the frame itself."] = "Zeigt den Tooltip der Einheit an, wenn der Mauszeiger über dem Fenster selbst schwebt."
L["Show this indicator's buffs in the exact order you arrange (the first 10 arranged buffs are guaranteed; any beyond follow the default sorting)."] = "Zeigt die Stärkungszauber dieses Indikators genau in der von Dir angeordneten Reihenfolge an (die ersten 10 angeordneten Stärkungszauber sind garantiert; alle weiteren folgen der Standard-Sortierung)."
L["Show Tick at Kick Ready Spot"] = "Markierung am Punkt für bereite Unterbrechung anzeigen"
L["Show Time Remaining"] = "Verbleibende Zeit anzeigen"
L["Show Timer Bar"] = "Timerleiste anzeigen"
L["Show Timer Text"] = "Timertext anzeigen"
L["Show Timer"] = "Timer anzeigen"
L["Show Title"] = "Titel anzeigen"
L["Show Tooltip Data"] = "Tooltip Daten anzeigen"
L["Show Tooltip For"] = "Tooltip anzeigen für"
L["Show Tooltip on Hover"] = "Tooltip beim Darüberfahren anzeigen"
L["Show Tooltip"] = "Tooltip anzeigen"
L["Show Tooltips"] = "Tooltips anzeigen"
L["Show top 15 entries instead of 8."] = "Die besten 15 Einträge anstelle von 8 anzeigen."
L["Show Top Line"] = "Oberste Zeile anzeigen"
L["Show Total Duration"] = "Gesamtdauer anzeigen"
L["Show total equipped durability above the character model, colored from green to red."] = "Zeigt die gesamte Haltbarkeit der angelegten Ausrüstung über dem Charaktermodell an, eingefärbt von Grün bis Rot."
L["Show Unit Target"] = "Ziel der Einheit anzeigen"
L["Show Upgrade Track"] = "Aufwertungspfad anzeigen"
L["Show Veteran"] = "Veteran anzeigen"
L["Show weapon oil and imbue icons at the front of this bar. They are weapon enchants rather than auras, so they show independently of the options above -- and the aura grid is shifted inward to make room for them, with every row shifting over by the same amount."] = "Zeigt Symbole für Waffenöl und -verzauberungen ganz vorne auf dieser Leiste an. Da es sich um Waffenverzauberungen und nicht um Auren handelt, werden sie unabhängig von den obigen Optionen angezeigt – und das Aurenraster wird nach innen verschoben, um Platz zu machen, wobei jede Reihe um denselben Betrag verschoben wird."
L["Show When Missing"] = "Anzeigen wenn fehlend"
L["Show When Solo"] = "Anzeigen wenn solo"
L["Show When Spellbook Is Open"] = "Anzeigen, wenn das Zauberbuch geöffnet ist"
L["Show When"] = "Anzeigen wenn"
L["Show While Mounted"] = "Anzeigen während aufgesessen"
L["Show who each spell is being cast on, exactly like the nameplate cast bars."] = "Zeigt an, auf wen jeder Zauber gewirkt wird, genau wie die Zauberleisten der Namensplaketten."
L["Show who the spell is being cast on, exactly like the nameplate cast bars."] = "Zeigt an, auf wen der Zauber gewirkt wird, genau wie die Zauberleisten der Namensplaketten."
L["Show Without Item in Bags"] = "Auch ohne Gegenstand in den Taschen anzeigen"
L["Show world latency instead of home latency."] = "Zeigt die Weltlatenz anstelle der Standortlatenz an."
L["Show World MS"] = "Welt-ms anzeigen"
L["Show your own class buffs on every spec, not only on the tracked healer spec."] = "Zeigt eigene Klassenstärkungszauber in allen Spezialisierungen an, nicht nur in der verfolgten Heilerspezialisierung."
L["Show"] = "Anzeigen"
L["Show/Hide Hitbox Overlay"]   = "Hitbox Überlagerung ein-/ausblenden"
L["Show/Hide on Preview"] = "In der Vorschau ein-/ausblenden"
L["Showing the '%s' override's value. Edit it from that override's editing mode."] = "Wert der Überschreibung '%s' wird angezeigt. Bearbeite ihn im Bearbeitungsmodus dieser Überschreibung."
L["Showing this aura from any caster; click for your casts only."] = "Zeigt diese Aura von jedem Zaubernden an; klicken, um nur Deine eigenen Zauber anzuzeigen."
L["Showing this aura from your casts only; click for any caster."] = "Zeigt diese Aura nur von Deinen eigenen Zaubern an; klicken für alle Zaubernden."
L["Shown At Cursor"] = "Am Mauszeiger anzeigen"
L["Shown"] = "Angezeigt"
L["Shows a bar that fills over the global cooldown."] = "Zeigt eine Leiste an, die sich über die globale Abklingzeit (GCD) füllt."
L["Shows a clickable list of online friends and guildmates in the Social and Guild button tooltips."] = "Zeigt eine anklickbare Liste von Online Freunden und Gildenmitgliedern in den Tooltips der Tasten „Soziales“ und „Gilde“ an."
L["Shows a colored overlay at the end of the cast bar representing your network latency for each spell. Helps you time spell queuing."] = "Zeigt eine farbige Überlagerung am Ende der Zauberleiste an, die Ihre Netzwerklatenz darstellt. Hilft beim Timing von Zauber-Anreihungen."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept."] = "Zeigt eine Countdown-Leiste unter dem Bestätigungs-Popup der Warteschlange an, die angibt, wie viel Zeit zum Annehmen bleibt."
L["Shows a faint white wash over each block on mouseover."] = "Zeigt beim Darüberfahren mit der Maus einen schwachen weißen Schleier über jedem Block an."
L["Shows a house or globe icon marking which latency each value is."] = "Zeigt ein Haus- oder Globus-Symbol an, um zu markieren, welcher Wert welche Latenz ist."
L["Shows a large on-screen alert (e.g. \"Player DIED!\") whenever a party or raid member dies, so you immediately notice deaths during dungeons and raids. Use Unlock Mode to reposition the alert."] = "Zeigt eine große Warnung auf dem Bildschirm an (z. B. 'Spieler GESTORBEN!'), wann immer ein Gruppen- oder Schlachtzugsmitglied stirbt. Nutzen Sie den Freigabemodus, um die Warnung zu verschieben."
L["Shows a large on-screen text when you enter and/or leave combat (e.g. \"+Combat\" / \"-Combat\"). Use the cog to set the display text, size, colors and which transitions are shown; use Unlock Mode to reposition the alert."] = "Zeigt einen großen Text auf dem Bildschirm an, wenn du den Kampf betrittst und/oder verlässt (z. B. \"+Kampf\" / \"-Kampf\"). Verwende das Zahnrad, um Anzeigetext, Größe, Farben und gezeigte Übergänge einzustellen; nutze den Freischaltmodus, um die Warnung neu zu positionieren."
L["Shows a map icon of the friend's region if they are not playing within your region"] = "Zeigt ein Kartensymbol der Region des Freundes an, wenn dieser nicht in Ihrer Region spielt"
L["Shows a movable strip of recent spell icons. Shift-drag to reposition."] = "Zeigt eine bewegliche Leiste der kürzlich gewirkten Zauber an. Shift-Ziehen zum Repositionieren."
L["Shows a player's RP title on their unit tooltip."] = "Zeigt den RP-Titel eines Spielers im Tooltip an."
L["Shows a popup with party and guild keystones when typing /keys."] = "Zeigt ein Popup mit den Mythisch+-Schlüsseln der Gruppe und Gilde an, wenn /keys eingegeben wird."
L["Shows a rest icon while your character is resting."] = "Zeigt ein Erholungs-Symbol an, während sich dein Charakter ausruht."
L["Shows a single Blood Plague debuff on enemy nameplates instead of one per copy (Blood Boil from weapon copies)."] = "Zeigt nur einen einzelnen 'Blutpest'-Schwächungszauber auf gegnerischen Namensplaketten an anstelle von einem pro Kopie (Siedendes Blut von Waffenkopien)."
L["Shows a small white tick mark on the cast bar at the point where the cast will be when your interrupt comes off cooldown."] = "Zeigt eine kleine weiße Markierung auf der Zauberleiste an dem Punkt an, an dem der Zauber sein wird, wenn Ihre Unterbrechung bereit ist."
L["Shows a small white tick mark where the cast will be when your interrupt comes off cooldown."] = "Zeigt eine kleine weiße Markierung dort an, wo sich der Zauber befindet, wenn Deine Unterbrechung wieder bereit ist."
L["Shows a special color for nameplates that another tank in your raid has aggro on."] = "Zeigt eine spezielle Farbe für Namensplaketten an, auf denen ein anderer Tank im Schlachtzug die Bedrohung hat."
L["Shows a special color for non caster/mini-boss enemies when you do not have aggro on them."] = "Zeigt eine spezielle Farbe für Nicht Zauberer/Mini-Bosse an, wenn Sie keine Bedrohung auf ihnen haben."
L["Shows a special color for non caster/mini-boss enemies when you have aggro on them."] = "Zeigt eine spezielle Farbe für Nicht Zauberer/Mini-Bosse an, wenn Sie Bedrohung auf ihnen haben."
L["Shows a standalone window with spell cast history as bars. Matches your Damage Meters styling."] = "Zeigt ein eigenständiges Fenster mit dem Verlauf der gewirkten Zauber als Leisten an. Passt zum Stil Ihres Schadensmeters."
L["Shows an envelope icon when you have unread mail."] = "Zeigt ein Briefumschlag-Symbol an, wenn du ungelesene Post hast."
L["Shows any debuff with a dispel type (Magic, Curse, Disease, Poison, Bleed), even if you cannot remove it"] = "Zeigt jeden Schwächungszauber mit einem Banntyp an (Magie, Fluch, Krankheit, Gift, Bluten), selbst wenn Du ihn nicht entfernen kannst"
L["Shows Blizzard's default icon slot background texture behind empty action bar slots."] = "Zeigt Blizzards standardmäßige Hintergrundtextur hinter leeren Aktionsleistenplätzen an."
L["Shows each healer's name before the number while in a raid. In a party the display always shows numbers only."] = "Zeigt in einem Schlachtzug den Namen jedes Heilers vor der Nummer an. In einer Gruppe werden immer nur Nummern angezeigt."
L["Shows elapsed / total duration (e.g. 0.4 / 2.0) instead of counting down from the total."] = "Zeigt die abgelaufene / Gesamtdauer an (z. B. 0.4 / 2.0) anstelle eines Countdowns."
L["Shows every debuff except the ones you or your pet apply"] = "Zeigt jeden Schwächungszauber außer denen an, die du oder dein Begleiter anwenden"
L["Shows full spell and ability descriptions in tooltips instead of just the name. Only enforced on login after you toggle this setting."] = "Zeigt vollständige Zauber- und Fähigkeitsbeschreibungen in Tooltips anstelle von nur dem Namen an. Wird erst nach dem nächsten Login wirksam."
L["Shows item level and secondary stats in the Character button's tooltip."] = "Zeigt Gegenstandsstufe und Sekundärwerte im Tooltip der Charaktertaste an."
L["Shows only crowd-control auras"] = "Zeigt nur Kontrollverlust-Auren (CC) an"
L["Shows only debuffs Blizzard flags as important"] = "Zeigt nur Schwächungszauber an, die von Blizzard als wichtig markiert wurden"
L["Shows only debuffs from Blizzard's curated raid-frame debuff set"] = "Zeigt nur Schwächungszauber aus Blizzards kuratiertem Schlachtzugsfenster-Set an"
L["Shows only debuffs not caused by any player or player pet (this is what shows most pve debuffs, do not check this while All Debuffs is selected!"] = "Zeigt nur Schwächungszauber an, die nicht von einem Spieler oder Begleiter verursacht wurden (dies zeigt die meisten PvE-Schwächungszauber an; nicht aktivieren, wenn 'Alle Schwächungszauber' ausgewählt ist!)."
L["Shows only external defensive cooldowns cast on the unit"] = "Zeigt nur externe defensive Abklingzeiten an, die auf die Einheit gewirkt wurden"
L["Shows only major defensive cooldowns"] = "Zeigt nur große defensive Abklingzeiten an"
L["Shows only the Buffs/Debuffs that appear on Raid Frames"] = "Zeigt nur die Stärkungs-/Schwächungszauber an, die auch im Schlachtzugsfenster erscheinen"
L["Shows only the Buffs/Debuffs you apply"] = "Zeigt nur die von Ihnen angewendeten Stärkungs-/Schwächungszauber an"
L["Shows only the Debuffs that appear on Raid Frames"] = "Zeigt nur die Schwächungszauber an, die auch im Schlachtzugsfenster erscheinen"
L["Shows only the Debuffs you apply"] = "Zeigt nur die von Ihnen angewendeten Schwächungszauber an"
L["Shows only the spells Blizzard flags as Important"] = "Zeigt nur die Zauber an, die Blizzard als wichtig markiert"
L["Shows only the stricter in-combat subset of the raid set"] = "Zeigt nur die strengere Kampf-Teilmenge des Schlachtzugs-Sets an"
L["Shows saved instance lockouts with boss kill progress on the minimap calendar button tooltip."] = "Zeigt gespeicherte Instanzzuweisungen mit Boss-Fortschritt im Tooltip des Minimap-Kalendersymbols an."
L["Shows silver and copper, not just gold."] = "Zeigt auch Silber und Kupfer an, nicht nur Gold."
L["Shows start as a small icon, and the keybind switches between the icon and the full windows. Turn off to show full windows and make the keybind hide and show them."] = "Startet als kleines Symbol, und die Tastenbelegung schaltet zwischen dem Symbol und den vollständigen Fenstern um. Deaktivieren, um vollständige Fenster anzuzeigen und die Tastenbelegung zum Ein- und Ausblenden zu nutzen."
L["Shows the 'Disable Feature' text below the teleport button. When off, the text is hidden and the window is 20px shorter."] = "Zeigt den Text 'Funktion deaktivieren' unter der Teleport Taste an. Wenn deaktiviert, wird der Text ausgeblendet und das Fenster ist 20px kürzer."
L["Shows the active talent loadout name."] = "Zeigt den Namen der aktiven Talentkonfiguration an."
L["Shows the approximate distance to your current target as movable on-screen text (default 30-35). Use the cog for format, alignment, and text size; use Unlock Mode to position or Anchor to your Player Frame."] = "Zeigt die ungefähre Entfernung zu Deinem aktuellen Ziel als verschiebbaren Text auf dem Bildschirm an (Standard 30-35). Verwende das Zahnrad für Format, Ausrichtung und Textgröße; nutze den Entsperren-Modus zur Positionierung oder verankere es an Deinem Spielerfenster."
L["Shows the approximate distance to your current target on its nameplate as a range bracket, e.g. 15+ when the target is 15-20 yards away."] = "Zeigt die ungefähre Entfernung zum aktuellen Ziel auf dessen Namensplakette als Bereich, z. B. 15+ bei 15-20 Metern Entfernung."
L["Shows the audio icon next to the volume bar."] = "Zeigt das Audiosymbol neben der Lautstärkeleiste an."
L["Shows the checked classes' mobility spell(s) counting down on cooldown. Nothing checked = feature disabled. Use Unlock Mode to reposition/resize."] = "Zeigt die Abklingzeit der Mobilitätszauber ausgewählter Klassen als Countdown an. Nichts ausgewählt = Funktion deaktiviert. Nutze den Freischaltmodus zum Neupositionieren/Skalieren."
L["Shows the coin icon next to the amount."] = "Zeigt das Münzsymbol neben dem Betrag an."
L["Shows the consumable rank (quality) diamond icon on action buttons."] = "Zeigt das Rauten-Symbol für den Rang (Qualität) von Verbrauchsgütern auf den Aktionstasten an."
L["Shows the Convert to Raid button, which reads Convert to Party while you are in a raid."] = "Zeigt die Taste 'In Schlachtzug umwandeln', die im Schlachtzug 'In Gruppe umwandeln' heißt."
L["Shows the currency icon next to the amount."] = "Zeigt das Währungssymbol neben dem Betrag an."
L["Shows the currency's description text in the tooltip. Turn off for a compact tooltip with just the name and the amount."] = "Zeigt den Beschreibungstext der Währung im Tooltip an. Ausschalten für einen kompakten Tooltip mit nur Name und Menge."
L["Shows the Disband button. It always asks before disbanding, but hiding it puts it out of misclick range for good."] = "Zeigt die Taste 'Auflösen'. Sie fragt immer nach, bevor die Gruppe aufgelöst wird -- ausgeblendet ist sie jedoch endgültig außer Reichweite von Fehlklicks."
L["Shows the icon next to the durability readout."] = "Zeigt das Symbol neben der Haltbarkeitsanzeige an."
L["Shows the item level on each item in the character sheet gear flyout (the popup of same-slot bag items that appears when hovering an equipped slot), coloured by quality."] = "Zeigt Gegenstandsstufen für alle Gegenstände im Ausrüstungs Flyout des Fenstercharakters an (das Aufklappmenü mit gleichen Taschengegenständen beim Fahren über einen angelegten Platz), eingefärbt nach Seltenheit."
L["Shows the item level on weapons and armor a vendor sells."] = "Zeigt die Gegenstandsstufe von Waffen und Rüstungsteilen an, die ein Händler verkauft."
L["Shows the items as a list instead of pages."] = "Zeigt die Gegenstände als Liste statt auf Seiten an."
L["Shows the map pin next to the zone name."] = "Zeigt die Kartennadel neben dem Zonennamen an."
L["Shows the marker icon next to the coordinates."] = "Zeigt das Markierungssymbol neben den Koordinaten an."
L["Shows the nameplate-style dragon badge on elite, rare elite, and rare targets."] = "Zeigt den Drachen Aufsatz im Stil von Namensplaketten bei Elite-, Rar-Elite- und Rar Zielen an."
L["Shows the online friend and guild counters."] = "Zeigt die Anzahl der Online-Freunde und Gildenmitglieder an."
L["Shows the profession icons next to the text."] = "Zeigt die Berufssymbole neben dem Text an."
L["Shows the raid target marker icon on boss frames."] = "Zeigt das Schlachtzugsreihenfolge-Symbol auf Bossfenstern an."
L["Shows the Role Check button. Turn it off and the remaining buttons close the gap."] = "Zeigt die Taste 'Rollenüberprüfung'. Ist sie ausgeschaltet, rücken die übrigen Tasten nach."
L["Shows the rotation-helper ring on the button holding the One Button Assist action."] = "Zeigt den Rotationshilfering auf dem Button an, der die Ein Tasten-Assistent-Aktion enthält."
L["Shows the target marker directly before the enemy name text. Uses its own size and does not use the Core Positions raid marker slot."] = "Zeigt die Zielmarkierung direkt vor dem Namen des Gegners an. Verwendet eine eigene Größe und belegt nicht den Schlachtzugs Markierungsplatz für „Kern Positionen“."
L["Shows the zone and the subzone together instead of the subzone alone."] = "Zeigt die Zone und die Teilzone zusammen anstelle der Teilzone allein an."
L["Shows tick marks on channeled spells. Only supported spells are shown, request missing spells on Discord."] = "Zeigt Markierungen bei kanalisierten Zaubern an. Nur unterstützte Zauber werden angezeigt, fehlende Zauber können auf Discord angefragt werden."
L["Shows where your interrupt will be ready during a cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "Zeigt an, wann Deine Unterbrechung während eines Zaubers bereit ist. \"Markierung\" kennzeichnet die genaue Stelle auf der Zauberleiste; \"Markierung + Leiste\" färbt zusätzlich das Zeitfenster ein, in dem Deine Unterbrechung verfügbar sein wird."
L["Shows where your interrupt will be ready during an enemy cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "Zeigt an, wann Ihre Unterbrechung während eines feindlichen Zaubers bereit sein wird. 'Markierung' markiert den exakten Punkt; 'Markierung + Leiste' färbt zudem das Zeitfenster ein, in dem Ihre Unterbrechung verfügbar sein wird."
L["Shows your free bag slots."] = "Zeigt deine freien Taschenplätze an."
L["Sidebar Icon Size"] = "Seitenleistensymbol Größe"
L["Sidebar Icons Color"] = "Seitenleisten Symbolfarbe"
L["Sidebar Icons"] = "Seitenleistensymbole"
L["Sidebar Settings"] = "Seitenleisten Einstellungen"
L["Sidebar Spacing"] = "Abstand der Seitenleiste"
L["Sidebar Visibility"] = "Seitenleisten Sichtbarkeit"
L["Sidebar Width"] = "Breite der Seitenleiste"
L["Sidebar"] = "Seitenleiste"
L["SIDEBAR"] = "SEITENLEISTE"
L["Silence\n(Focus)"] = "Stille\n(Fokus)"
