L["Thank you for helping test EllesmereUI during beta! During testing, many systemic changes were made to build the foundation for a stable, flexible addon going forward.\n\nTo ensure a clean experience for everyone, all settings have been automatically reset. You will need to reconfigure your UI. We apologize for the inconvenience, and appreciate your patience.\n\nPrevious profile exports are no longer compatible and will need to be re-created."] = "Vielen Dank für Ihre Hilfe beim Testen von EllesmereUI während der Beta! Während der Testphase wurden viele systemische Änderungen vorgenommen, um die Basis für ein stabiles Addon zu schaffen.\n\nUm eine saubere Erfahrung zu garantieren, wurden alle Einstellungen automatisch zurückgesetzt. Sie müssen Ihr UI neu konfigurieren. Wir entschuldigen uns für die Unannehmlichkeiten.\n\nVorherige Profilexporte sind nicht mehr kompatibel und müssen neu erstellt werden."
L["Thank you for making EllesmereUI possible."] = "Vielen Dank, dass Du EllesmereUI möglich machst."
L["Thank you to all who support EllesmereUI and its incredible support team!"] = "Vielen Dank an alle, die EllesmereUI und sein fantastisches Support-Team unterstützen!"
L["The \"you have been invited to a group\" dialogs, with your role and Accept / Decline."] = "Die 'Du wurdest in eine Gruppe eingeladen' Dialoge mit Deiner Rollenauswahl sowie Annehmen / Ablehnen."
L["The \"You received\" popups for loot, currency, and upgrades."] = "Die „Du erhältst“-Popups für Beute, Währung und Aufwertungen."
L["The achievement window: categories, rows, progress bars, and search."] = "Das Erfolgsfenster: Kategorien, Zeilen, Fortschrittsbalken und Suche."
L["The active override's custom %s is bound to this page. Leave the %s tab to switch to another override."] = "Der eigene %s der aktiven Überschreibung ist an diese Seite gebunden. Verlasse den Reiter '%s', um zu einer anderen Überschreibung zu wechseln."
L["The addon manager: list rows, checkboxes, and buttons."] = "Der Addon Manager: Zeilen, Kontrollkästchen und Buttons."
L["The amount of damage you can take"] = "Die Menge an Schaden, die Sie einstecken können"
L["The Armory (%d)"] = "Die Rüstkammer (%d)"
L["The Armory"] = "Die Rüstkammer"
L["The auction house: browse, sell, and my auctions views."] = "Das Auktionshaus: Durchsuchen, Verkaufen und Meine Auktionen."
L["The background colour behind Dark Mode bars (Unit Frames, Raid Frames, Resource Bars)."] = "Die Hintergrundfarbe hinter Leisten im Dunkelmodus (Einheitenfenster, Schlachtzugsfenster, Ressourcenleisten)."
L["The class and profession trainer window: skill list, train button, and cost display."] = "Das Klassen- und Berufe-Trainerfenster: Fertigkeitenliste, Ausbilden Taste und Kostenanzeige."
L["The class resource bar gains a spec picker to choose which specs show it, matching the power and health bars."] = "Die Klassenressourcenleiste erhält eine Spezialisierungs-Auswahl, um festzulegen, welche Spezialisierungen sie anzeigen, passend zu den Energie- und Gesundheitsleisten."
L["The Combat Indicator is not available for the Focus frame."] = "Die Kampfanzeige ist für das Fokusfenster nicht verfügbar."
L["The customer crafting orders window: browse, order form, and my orders."] = "Das Handwerksauftrags Fenster für Kunden: Durchsuchen, Auftragsformular und Meine Aufträge."
L["The damage and tank cut of Light of Nitex. The same style refocused on your rotation, procs, and cooldowns front and center."] = "Die Schaden- und Tank-Variante von Light of Nitex. Der gleiche Stil, neuausgerichtet auf deine Rotation, Procs und Abklingzeiten direkt im Zentrum."
L["The damage dealer cut of Midnight Lily. A focused, low-clutter layout that keeps your rotation and cooldowns front and center."] = "Die Schadensverursacher-Variante von Midnight Lily. Ein fokussiertes, aufgeräumtes Layout, das Ihre Rotation und Abklingzeiten in den Mittelpunkt stellt."
L["The dark counterpart to Lazar's Dawn. A moody, high-contrast layout that keeps focus locked on the fight."] = "Das dunkle Gegenstück zu Lazar's Dawn. Ein stimmungsvolles, kontrastreiches Layout, das den Fokus voll auf den Kampf richtet."
L["The default EllesmereUI look"] = "Das standardmäßige EllesmereUI-Aussehen"
L["The delve difficulty window: tier dropdown, reward list and Enter button. The Map Properties row is left stock -- it is a Blizzard widget display and is not safe to restyle."] = "Das Tiefen-Schwierigkeitsfenster: Stufen-Drop-down, Belohnungsliste und 'Betreten' Schaltfläche. Die Zeile 'Karten-Eigenschaften' bleibt Standard – sie ist eine Blizzard-Widget Anzeige und nicht sicher umzugestalten."
L["The dispel type icon gains an Icon Size slider in its cog menu so you can make it larger or smaller."] = "Das Bannsymbol-Icon erhält einen Schieberegler für die Icon-Größe im Zahnradmenü."
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "Die Anzeigesprache für das EllesmereUI-Konfigurationsfenster. 'Auto' folgt Ihrem Spiel-Client. Nicht übersetzter Text bleibt Englisch."
L["The Dreamrift (Raid)"] = "Der Traumbruch (Schlachtzug)"
L["The Dreamrift"] = "Der Traumbruch"
L["the EllesmereUI theme"] = "das EllesmereUI-Design"
L["The flat fill colour bars use when Dark Mode is enabled (Unit Frames, Raid Frames, Resource Bars)."] = "Die flache Füllfarbe, die Leisten verwenden, wenn der Dunkelmodus aktiviert ist."
L["The gap between a nested menu's icons and the entry that opens it."] = "Der Abstand zwischen den Symbolen eines verschachtelten Menüs und dem Eintrag, der es öffnet."
L["The gem socketing window with squared gem slots."] = "Das Sockelfenster mit quadratischen Edelsteinplätzen."
L["THE GREAT VAULT"] = "DIE GROSSE SCHATZKAMMER"
L["The Guild & Communities window: roster, chat, and the community list."] = "Das Gilde & Communities-Fenster: Mitgliederliste, Chat und Community Liste."
L["The highlight overlay that appears on a spell button while it is the active/current action. Disable to hide it."] = "Die Hervorhebungs-Überlagerung, die auf einer Zaubertaste erscheint, während sie die aktive Aktion ist. Deaktivieren zum Ausblenden."
L["The housing dashboard window background, border, and title bar."] = "Hintergrund, Rahmen und Titelleiste des Housing Übersichtsfensters."
L["The interrupt flash now clears the instant a target dies, so the cast bar no longer looks squished by the death animation."] = "Das Aufblitzen bei Unterbrechung verschwindet nun sofort, wenn das Ziel stirbt, sodass die Zauberleiste durch die Todesanimation nicht mehr gestaucht aussieht."
L["The item conversion window (catalyst and similar kiosks)."] = "Das Gegenstandsumwandlungs Fenster (Katalysator und ähnliche Konsolen)."
L["The item preview / transmog dressing room window."] = "Das Gegenstandsvorschau- / Transmog-Anproberaumfenster."
L["The item upgrade window: upgrade slot, track selector, cost, and the currency strip."] = "Das Gegenstandsaufwertungs-Fenster: Aufwertungsplatz, Pfadauswahl, Kosten und Währungsleiste."
L["The loot window: item rows with squared icons, kept item quality colors."] = "Das Beutenfenster: Gegenstandszeilen mit quadratischen Symbolen und beibehaltenen Gegenstandsqualitäts Farben."
L["The macro editor: tabs, icon grid, text well, and buttons."] = "Der Makro-Editor: Reiter, Symbolraster, Textfeld und Buttons."
L["The mailbox: inbox rows, send mail, open mail, and attachment slots."] = "Das Postfach: Posteingangszeilen, Nachricht senden, Nachricht öffnen und Anhang-Plätze."
L["the Modern background style"] = "der Modern Hintergrundstil"
L["the module"] = "das Modul"
L["The monthly calendar grid, event dialogs, and navigation arrows."] = "Das monatliche Kalenderraster, Event-Dialoge und Navigationspfeile."
L["The most cast bars shown at once. Extra casters take a bar as soon as one frees up."] = "Die maximale Anzahl gleichzeitig angezeigter Zauberleisten. Zusätzliche Zaubernde erhalten eine Leiste, sobald eine frei wird."
L["The need / greed / pass roll popups, with a squared icon and a flat roll timer."] = "Die 'Bedarf / Gier / Passen'-Würfelfenster mit einem quadratischen Symbol und einem flachen Würfeltimer."
L["The NPC dialog window: greeting text, gossip and quest options, and goodbye button."] = "Das NPC-Dialogfenster: Begrüßungstext, Gesprächs- und Questoptionen sowie Auf-Wiedersehen Taste."
L["The NPC quest window: quest detail, progress, and reward panels plus the multi-quest greeting list."] = "Das NPC Questfenster: Questdetails, Fortschritt, Belohnungsfenster und die Begrüßungsliste bei mehreren Quests."
L["The overlay that appears on the icon when you hover your mouse over a spell button"] = "Die Überlagerung, die auf dem Icon erscheint, wenn Sie mit der Maus über eine Zaubertaste fahren"
L["The overlay that appears on the icon when you press and hold a spell button"] = "Die Überlagerung, die auf dem Icon erscheint, wenn Sie eine Zaubertaste gedrückt halten"
L["The panel the minimap Group Finder eye shows on hover: queue titles, role icons and counts, and time in queue."] = "Das Feld, das das Dungeonsuche-Auge an der Minimap beim Drüberbewegen anzeigt: Warteschlangentitel, Rollensymbole und -anzahlen sowie Zeit in der Warteschlange."
L["The pending-rolls window: encounter picker, roll timer, and the result rows."] = "Das Fenster für ausstehende Würfe: Bossauswahl, Würfeltimer und die Ergebniszeilen."
L["The Pet Bar cannot use group-based visibility."] = "Die Begleiterleiste kann keine gruppenbasierte Sichtbarkeit nutzen."
L["The Player Spells window: talents, spec selection, and the spellbook."] = "Das Spielerzauber Fenster: Talente, Spezialisierungsauswahl und Zauberbuch."
L["The player-to-player trade window: frame, both item columns, the enchant slots, money rows and buttons. Item icons are squared and carry a rarity border. Both portraits are removed, as on every other window."] = "Das Handelsfenster zwischen Spielern: Rahmen, beide Gegenstandsspalten, Verzauberungsplätze, Geldzeilen und Schaltflächen. Gegenstandssymbole werden quadratisch mit Seltenheitsrahmen. Beide Porträts werden entfernt, wie bei jedem anderen Fenster."
L["The profession crafting window: recipe list, schematic, specializations, and crafting orders."] = "Das Berufe Handwerksfenster: Rezeptliste, Schemata, Spezialisierungen und Handwerksaufträge."
L["The professions overview book with squared icons and flat progress bars."] = "Das Berufe Übersichtsbuch mit quadratischen Symbolen und flachen Fortschrittsbalken."
L["the Randomly trigger"] = "der Zufallssuslöser"
L["The ready check prompt with its Yes / No buttons, plus the initiator's response list."] = "Die Bereitschaftsabfrage-Aufforderung mit ihren 'Ja' / 'Nein' Tasten sowie die Antwortliste des Initiators."
L["The ready check prompt with its Yes / No buttons."] = "Die Bereitschaftsabfrage Aufforderung mit ihren 'Ja' / 'Nein' Tasten."
L["The recipe preview window shown from a linked recipe or an inspected crafter."] = "Das Rezept Vorschaufenster für verlinkte Rezepte oder bei der Betrachtung eines Handwerkers."
L["The Ring of Valor"] = "Der Ring der Tapferkeit"
L["The Rookery"] = "Das Brutgebiet"
L["The signature EllesmereUI layout exactly as designed. Vibrant class colors, clear cd tracking, and every module working in harmony."] = "Das unverkennbare EllesmereUI-Layout exakt wie entworfen. Kräftige Klassenfarben, klare CD-Verfolgung und alle Module in perfekter Harmonie."
L["The size of your mana pool"] = "Die Größe Ihres Manavorrats"
L["The Social window frame, border, title bar, Battle.net bar, search boxes, filter dropdowns and buttons. List contents and the side tab icons stay untouched."] = "Der Rahmen des Geselligkeits-Fensters, die Kontur, die Titelleiste, die Battle.net Leiste, Suchfelder, Filter Dropdowns und Buttons. Listeninhalte und die seitlichen Reiter Symbole bleiben unverändert."
L["The spell picker now ends with a Missing Spells? shortcut that opens Blizzard's Cooldown Manager so you can add spells that are not listed."] = "Die Zauberauswahl endet nun mit einer Verknüpfung 'Fehlende Zauber?', die Blizzards Abklingzeit Manager öffnet, um nicht aufgelistete Zauber hinzuzufügen."
L["The standard buff grid"] = "Das Standard Stärkungszauber Raster"
L["The standard debuff grid"] = "Das Standard Schwächungszauber Raster"
L["The transmogrification window at the transmogrifier."] = "Das Transmogrifikationsfenster beim Transmogrifizierer."
L["The vendor window: item list, buyback, and bottom money bar."] = "Das Händlerfenster: Gegenstandsliste, Rückkauf und untere Geldleiste."
L["The Voidspire (Raid)"] = "Die Leerenfestung (Schlachtzug)"
L["The Voidspire"] = "Die Leerenfestung"
L["The widest angle a nest's entries may spread over. They stay on one ring for as long as they fit inside it; the rest go onto a second ring further out."] = "Der maximale Winkel, über den sich die Einträge eines Untermenüs verteilen dürfen. Sie bleiben auf einem Ring, solange sie darauf Platz haben; der Rest wird auf einem zweiten, weiter außen liegenden Ring platziert."
L["The widest angle a nest's entries may spread over."] = "Der maximale Winkel, über den sich die Einträge eines Untermenüs verteilen dürfen."
L["The world map window chrome and the quest log side panel."] = "Der Rahmen des Weltkartenfensters und die Questlog-Seitenleiste."
L["Themed Blizzard frames: window skins, tooltips, menus, popups, Dragon Riding HUD."] = "Themed Blizzard Fenster: Fenster Skins, Tooltips, Menüs, Popups, Drachenreiten HUD."
L["These settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Diese Einstellungen bevorzugen Bildrate und visuelle Klarheit gegenüber Umgebungsdetails. Texturen bleiben hochauflösend."
L["These specs hold override values that no group's editing mode can reach anymore (left behind by membership changes). They still apply. Remove one to return that spec to the shared default."] = "Diese Spezialisierungen enthalten Überschreibungswerte, die von keinem Bearbeitungsmodus einer Gruppe mehr erreicht werden können (zurückgeblieben durch Mitgliederänderungen). Sie finden weiterhin Anwendung. Entferne eine, um diese Spezialisierung zum gemeinsamen Standard zurückzusetzen."
L["Thick Outline"] = "Dicke Kontur"
L["Thick"] = "Dick"
L["Thickness of any Pixel Glow assigned to this bar's buttons. Assign glows by right-clicking an icon in the preview."] = "Dicke des Pixel Leuchtens für die Tasten dieser Leiste. Zuweisung per Rechtsklick auf ein Icon in der Vorschau."
L["Thickness"] = "Dicke"
L["Thin Line Bottom"] = "Dünne Linie unten"
L["Thin Line Top"] = "Dünne Linie oben"
L["Thin"] = "Dünn"
L["Third Timer"] = "Dritter Timer"
L["This Action Bar is also used as the Moonkin Form bar.\nChanging spells on a Druid for this bar will also change them on your Moonkin Form bar."] = "Diese Aktionsleiste wird auch für die Moonkin-Gestalt genutzt.\nÄnderungen an dieser Leiste betreffen auch die Leiste der Moonkin-Gestalt."
L["this action bar"] = "diese Aktionsleiste"
L["This bar has an Additional Bar Offset (X %1$s, Y %2$s) set in its options. Unlock mode shows the base position; the offset re-applies when you exit."] = "Diese Leiste hat einen zusätzlichen Leistenversatz (X %1$s, Y %2$s) in ihren Optionen eingestellt. Der Freigabemodus zeigt die Basisposition; der Versatz wird nach dem Beenden wieder angewendet."
L["This bar sizes its blocks itself, so the width is not this block's to choose."] = "Diese Leiste skaliert ihre Blöcke selbst, daher kann die Breite für diesen Block nicht gewählt werden."
L["This bar will always be attached to your focus target's nameplate"] = "Diese Leiste wird immer an der Namensplakette Deines Fokusziels verankert"
L["This bar will only show if you have an enemy targeted"] = "Diese Leiste wird nur angezeigt, wenn Sie einen Feind anvisiert haben"
L["this bar"] = "diese Leiste"
L["This block is already the 'Fill Remaining Space' block. Check another block to move the role."] = "Dieser Block ist bereits der Block für 'Restlichen Platz füllen'. Wähle einen anderen Block, um die Rolle zu verschieben."
L["This cannot be undone. Export your own profile as a backup first."] = "Dies kann nicht rückgängig gemacht werden. Exportiere dein eigenes Profil zuerst als Backup."
L["This change requires a UI reload to take effect."] = "Diese Änderung erfordert ein UI-Neuladen, um wirksam zu werden."
L["This control recently changed direction: it now copies FROM the frame you choose. Confirming will copy all shared settings FROM %1$s TO %2$s."] = "Diese Einstellung hat kürzlich die Richtung geändert: Sie kopiert jetzt VON dem gewählten Fenster. Das Bestätigen kopiert alle geteilten Einstellungen VON %1$s NACH %2$s."
L["This element cannot use group-based visibility."] = "Dieses Element kann keine gruppenbasierte Sichtbarkeit nutzen."
L["This element doesn't support both Height and Width matching"] = "Dieses Element unterstützt nicht die gleichzeitige Anpassung von Höhe und Breite"
L["This element will only show while you are inside a house or plot"] = "Dieses Element wird nur angezeigt, während Du Dich in einem Haus oder auf einem Grundstück befindest"
L["This element will only show while you are mounted"] = "Dieses Element wird nur angezeigt, während Du aufgesessen bist"
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "Dieser Export enthält profilübergreifende Einstellungen (darunter Quality-of-Life Optionen, Hovercast und mehr), die beim Importieren überschrieben werden und gewöhnlich nicht in Standard Profilen geteilt werden sollten. Dies wird für die öffentliche Weitergabe von Profilen NICHT EMPFOHLEN."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity."] = "Diese Funktion optimiert Ihre Grafikeinstellungen für die beste Kombination aus hohen FPS und visueller Klarheit."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\nShadow Quality - Fair (balanced quality/FPS)\nLiquid Detail - Disabled\nParticle Density - Set to Ultra (keeps important spell effects)\nSSAO (Ambient Occlusion) - Disabled\nDepth Effects - Disabled\nCompute Effects - Disabled\nOutline Mode - Disabled\nTexture Resolution - Set to High\nSpell Density - Set to Essential\nProjected Textures - Enabled (needed for ground effects)\nView Distance - Reduced to 1\nEnvironment Detail - Reduced to 1\nGround Clutter - Reduced to 1\nRaid/Dungeon Settings - Uses same settings everywhere\nResample Sharpening - Enabled (crisper image)\nContrast - Boosted by +10 (if currently 55 or below)\nEnable Reverb - Disabled (spell and interrupt audio cues stay crisp)\n\nThese settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Diese Funktion optimiert Ihre Grafikeinstellungen im Spiel für die beste Kombination aus hohen FPS und visueller Klarheit.\n\nSie können alle Änderungen jederzeit rückgängig machen, indem Sie auf 'Meine Einstellungen wiederherstellen' klicken.\n\n\nWas wir ändern:\n\nSchattenqualität - Gut (ausgewogen)\nFlüssigkeitsndetails - Deaktiviert\nPartikeldichte - Ultra (erhält wichtige Zaubereffekte)\nSSAO - Deaktiviert\nTiefeneffekte - Deaktiviert\nBerechnungseffekte - Deaktiviert\nKonturmodus - Deaktiviert\nTexturauflösung - Hoch\nZauberdichte - Essenziell\nProjizierte Texturen - Aktiviert (wichtig für Bodeneffekte)\nSichtweite - Reduziert auf 1\nUmgebungsdetails - Reduziert auf 1\nBodenobjekte - Reduziert auf 1\nSchlachtzugs-/Dungeon-Einstell. - Gleiche Einstell. überall\nResample-Schärfung - Aktiviert\nKontrast - Erhöht um +10 (wenn aktuell 55 oder weniger)\nHall aktivieren - Deaktiviert (Zauber- und Unterbrechungssignale bleiben klar)\n\nDiese Einstellungen bevorzugen Bildrate vor Umgebungsdetails. Texturen bleiben hochauflösend."
L["This feature requires Snap Elements to be enabled"] = "Diese Funktion erfordert, dass das Einrasten von Elementen aktiviert ist"
L["This feature runs continuous range checks against every visible enemy nameplate. It is one of the more expensive features in EllesmereUI and can measurably increase CPU usage in crowded areas."] = "Diese Funktion führt kontinuierliche Reichweitenprüfungen für jede sichtbare feindliche Namensplakette aus. Sie gehört zu den leistungshungrigeren Funktionen von EllesmereUI und kann in belebten Gebieten die CPU-Auslastung spürbar erhöhen."
L["This group's custom Debuff Manager can only be activated or edited while playing one of its specs."] = "Der eigene Schwächungszauber Manager dieser Gruppe kann nur aktiviert oder bearbeitet werden, während Du eine ihrer Spezialisierungen spielst."
L["this indicator"] = "dieser Indikator"
L["This is the full overlay that swipes from right to left on the icon during its cast duration"] = "Dies ist die vollständige Überlagerung, die während der Zauberdauer von rechts nach links über das Icon streicht."
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "Dies ist das Zauberreihenfolge-Zeitfenster (Spell Queue Window). Es verhindert, dass zu viele Zauber gleichzeitig angereiht werden, was das Spiel träge wirken lässt. Empfohlen wird: 200 + lokaler Ping. Wenn Sie unsicher sind, lassen Sie den Wert auf 400."
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally ~150 for melee and ~300 for casters. Higher if you have high local ping."] = "Dies ist das Zauberreihenfolge-Zeitfenster. Es verhindert zu viele Zauber-Anreihen auf einmal. Empfohlen werden ~150 für Nahkämpfer und ~300 für Zauberwirker. Höher bei hohem Ping."
L["This is where you can control the settings of Unlock Mode.\n\nElements can be repositioned by dragging or arrow keys (+shift)\nAnchor, Height Match, or Width match any element.\nSnapping is based on closest element, but you can snap only to\n a specific element via right click or the settings icon."] = "Hier steuern Sie die Einstellungen des Freigabemodus.\n\nElemente per Ziehen oder Pfeiltasten (+Shift) bewegen.\nAnker, Höhe oder Breite an jedes Element anpassen.\nDas Einrasten basiert auf dem nächsten Element, kann aber per Rechtsklick auf ein bestimmtes Element fixiert werden."
L["This makes it so the width of the cast bar includes the icon, rather than placing it to the left of the cast bars width."] = "Bewirkt, dass das Icon in die Breite der Zauberleiste eingerechnet wird, anstatt es links daneben zu platzieren."
L["This option allows you to set custom frame sizing and positioning to different raid sizes. Note: This does NOT resize/reposition frames while in combat, if players join/leave mid combat it will resize after combat completes."] = "Ermöglicht benutzerdefinierte Fenstergrößen/-positionen für verschiedene Schlachtzugsgrößen. Hinweis: Dies geschieht NICHT im Kampf, sondern erst nach Kampfende."
L["This option applies to bar-type resources only (pips use stack counts)."] = "Diese Option gilt nur für leistenspezifische Ressourcen (punktbasierte Ressourcen nutzen Stapelanzahlen)."
L["This option applies to pip-type resources only."] = "Diese Option gilt nur für punktbasierte Ressourcen."
L["This option can't be used while Expand Power Bar if No Resource is enabled."] = "Diese Option kann nicht genutzt werden, wenn 'Energieleiste erweitern, wenn keine Ressource' aktiviert ist."
L["This option can't be used while Shift Elements if No Resource is enabled."] = "Diese Option kann nicht genutzt werden, wenn 'Elemente verschieben, wenn keine Klassenressource' aktiviert ist."
L["This option can't be used while you have the Power Bar Height Matched in the Unlock Mode."] = "Diese Option kann nicht verwendet werden, solange im Freigabemodus 'Ressourcenleisten Höhe anpassen' aktiviert ist."
L["This option does not apply while Anchor to Cursor is enabled"] = "Diese Option ist nicht verfügbar, solange 'An Cursor verankern' aktiviert ist"
L["This option does not work with Blizzard Bars. Please use Blizzard Edit Mode."] = "Diese Option funktioniert nicht mit Blizzard Leisten. Bitte nutzen Sie den Blizzard Bearbeitungsmodus."
L["This option is currently under maintenance"] = "Diese Option wird derzeit gewartet"
L["This option is disabled while a Center Text is selected."] = "Diese Option ist deaktiviert, solange ein zentrierter Text ausgewählt ist."
L["This option is not available for custom shaped icons"] = "Diese Option ist für benutzerdefinierte Icon-Formen nicht verfügbar"
L["This option is not supported for this bar type"] = "Diese Option wird für diesen Leistentyp nicht unterstützt"
L["This option is now controlled by the Raid Frames addon"] = "Diese Option wird jetzt durch das Schlachtzugsfenster Addon gesteuert"
L["This option is only available for formats that display a percentage."] = "Diese Option ist nur für Formate verfügbar, die einen Prozentsatz anzeigen."
L["This option is only available for the Custom Color Theme"] = "Diese Option ist nur für das benutzerdefinierte Farbedesign verfügbar"
L["This option is only available when Portrait Mode is Detached."] = "Diese Option ist nur verfügbar, wenn der Porträtmodus 'Gelöst' ist."
L["This option is only used by the Basic border."] = "Diese Option wird nur vom Standard Rahmen verwendet."
L["This option only affects Raid Buffs and Paladin Beacons"] = "Diese Option betrifft nur Schlachtzugs Buffs und Paladin Flammen"
L["This option requires %1$s to be %2$s"] = "Diese Option erfordert, dass %1$s auf %2$s gesetzt ist"
L["This option requires %s to be enabled"] = "Diese Option erfordert, dass %s aktiviert ist"
L["This option requires a Border Size above 0."] = "Diese Option erfordert eine Rahmengröße über 0."
L["This option requires a Class Icon other than None."] = "Diese Option erfordert ein anderes Klassensymbol als 'Keines'."
L["This option requires a custom glow to be selected"] = "Diese Option erfordert, dass ein benutzerdefiniertes Leuchten ausgewählt ist"
L["This option requires a custom thickness to be set."] = "Diese Option erfordert die Festlegung einer benutzerdefinierten Dicke."
L["This option requires a detached position to be active."] = "Diese Option erfordert, dass eine gelöste Position aktiv ist."
L["This option requires a dropdown selection other than Above Health Bar"] = "Diese Option erfordert eine andere Auswahl als 'Über der Gesundheitsleiste'"
L["This option requires a Duration Text position other than None"] = "Diese Option erfordert eine andere Dauertext-Position als 'Keine'"
L["This option requires a Glow Type other than None"] = "Diese Option erfordert einen anderen Leuchttyp als 'Keines'"
L["This option requires a gradient to be set"] = "Diese Option erfordert, dass ein Farbverlauf festgelegt ist"
L["This option requires a Health Text format other than None"] = "Diese Option erfordert ein anderes Gesundheitstext Format als 'Keines'"
L["This option requires a Name Text position other than None"] = "Diese Option erfordert eine andere Namenstext Position als 'Keine'"
L["This option requires a non-custom button shape"] = "Diese Option erfordert eine standardmäßige Tastenform"
L["This option requires a non-custom shape to be selected"] = "Diese Option erfordert, dass eine standardmäßige Form ausgewählt ist"
L["This option requires a non-custom shaped action bar"] = "Diese Option erfordert eine standardmäßig geformte Aktionsleiste"
L["This option requires a perpendicular Group Growth"] = "Diese Option erfordert ein senkrechtes Gruppenwachstum"
L["This option requires a Power Text format other than None"] = "Diese Option erfordert ein anderes Energietext Format als 'Keines'"
L["This option requires a Stacks Text position other than None"] = "Diese Option erfordert eine andere Stapeltext Position als 'Keine'"
L["This option requires a text position other than none."] = "Diese Option erfordert eine andere Textposition als 'Keine'."
L["This option requires a text selection other than none."] = "Diese Option erfordert eine andere Textauswahl als 'Keine'."
L["This option requires a text to be assigned"] = "Diese Option erfordert, dass ein Text zugewiesen ist"
L["This option requires Add Friendly Boss Group to be set to Healers or Always."] = "Diese Option erfordert, dass 'Freundliche Bossgruppe hinzufügen' auf 'Heiler' oder 'Immer' gesetzt ist."
L["This option requires an aura or indicator to be assigned"] = "Diese Option erfordert, dass eine Aura oder ein Indikator zugewiesen ist"
L["This option requires Blizzard Style Action Bars to be disabled"] = "Diese Option erfordert, dass 'Aktionsleisten im Blizzard Stil' deaktiviert sind"
L["This option requires Class Colors to be disabled"] = "Diese Option erfordert, dass 'Klassenfarben' deaktiviert sind"
L["This option requires Class Resource to be set to Modern."] = "Diese Option erfordert, dass 'Klassenressource' auf 'Modern' gesetzt ist."
L["This option requires Display Style to be set to Icon"] = "Diese Option erfordert, dass der Anzeigestil auf 'Symbol' eingestellt ist"
L["This option requires Display Style to be set to Text"] = "Diese Option erfordert, dass der Anzeigestil auf 'Text' eingestellt ist"
L["This option requires exactly 2 rows"] = "Diese Option erfordert exakt 2 Zeilen"
L["This option requires Fill Color to be set to Custom"] = "Diese Option erfordert, dass 'Füllfarbe' auf 'Benutzerdefiniert' gesetzt ist"
L["This option requires Icon Shape to be set to None or Cropped"] = "Diese Option erfordert, dass die Symbolform auf 'Keine' oder 'Beschnitten' gesetzt ist"
L["This option requires Pixel Glow to be the selected glow type"] = "Diese Option erfordert, dass 'Pixel Leuchten' als Leuchttyp ausgewählt ist"
L["This option requires Portrait Mode to be set to Detached."] = "Diese Option erfordert, dass der Porträtmodus auf 'Gelöst' gesetzt ist."
L["This option requires Set UI Scale to 0.5333 to be disabled"] = "Diese Option erfordert, dass 'UI-Skalierung auf 0.5333 festlegen' deaktiviert ist"
L["This option requires Show Tanks in Extra Group or a bound hotkey."] = "Diese Option erfordert 'Tanks in Extra Gruppe anzeigen' oder eine zugewiesene Taste."
L["This option requires Show Tooltips to be set to hide tooltips"] = "Diese Option erfordert, dass 'Tooltips anzeigen' auf das Ausblenden von Tooltips eingestellt ist"
L["This option requires Subtitle Text to include the Guild Name"] = "Diese Option erfordert, dass der Untertiteltext den Gildenrahmen enthält"
L["This option requires the Border Style to be set to Solid"] = "Diese Option erfordert, dass der Rahmenstil auf 'Einfarbig' gesetzt ist"
L["This option requires the module to be enabled"] = "Diese Option erfordert, dass das Modul aktiviert ist"
L["This option requires the position setting to be detached"] = "Diese Option erfordert, dass die Positionseinstellung auf 'Gelöst' gesetzt ist"
L["This option requires Threshold Settings to be disabled"] = "Diese Option erfordert, dass die Schwellenwert Einstellungen deaktiviert sind"
L["This option Show Duration (Inside Cog) Enabled"] = "Diese Option 'Dauer anzeigen (Im Zahnrad)' ist aktiviert"
L["This override has no indicators for this spec, so nothing shows here until you add some."] = "Diese Überschreibung besitzt keine Indikatoren für diese Spezialisierung, daher wird hier nichts angezeigt, bis Du welche hinzufügst."
L["This overwrites this action menu's current settings. Its actions, name, and keybind are not changed."] = "Dies überschreibt die aktuellen Einstellungen dieses Aktionsmenüs. Seine Aktionen, sein Name und seine Tastenbelegung werden nicht geändert."
L["This page is excluded from overrides."] = "Diese Seite ist von Überschreibungen ausgeschlossen."
L["This preset"] = "Diese Voreinstellung"
L["This profile already holds 16 action menus"] = "Dieses Profil enthält bereits 16 Aktionsmenüs"
L["This profile string does not carry any global settings."] = "Dieser Profil String enthält keine globalen Einstellungen."
L["This resets every EUI addon, not just the current one."] = "Dies setzt jedes EUI Addon zurück, nicht nur das aktuelle."
L["This setting requires a UI reload to take effect."] = "Diese Einstellung erfordert ein UI Neuladen, um wirksam zu werden."
L["This spec doesn't have this spell."] = "Diese Spezialisierung besitzt diesen Zauber nicht."
L["this spec"] = "diese Spezi"
L["This spell is already being used on "] = "Dieser Zauber wird bereits verwendet auf "
L["This spell is already being used on %s"] = "Dieser Zauber wird bereits verwendet auf %s"
L["This spell"] = "Dieser Zauber"
L["This string is a FULL ACCOUNT export. It replaces your account-wide settings with the sender's, including Quality of Life, HoverCast bindings, Cooldown Manager spell setups, unlock anchors, UI scale, and profile keybinds -- not just a profile. Your other profiles are kept, but a profile with the same name is replaced."] = "Dieser String ist ein VOLLSTÄNDIGER ACCOUNT Export. Er ersetzt deine accountweiten Einstellungen durch die des Absenders – einschließlich Quality-of-Life Optionen, HoverCast Tastenbelegungen, Zauberkonfigurationen des Abklingzeiten Managers, Ankerpunkte, UI-Skalierung und Profil Tastenbelegungen (nicht nur ein einzelnes Profil). Deine anderen Profile bleiben erhalten, aber ein Profil mit demselben Namen wird überschrieben."
L["This will change the color of your bar if you have more than your chosen number of stacks"] = "Dies ändert die Farbe Ihrer Leiste, wenn Sie mehr als die gewählte Anzahl an Stapeln haben"
L["This will create a fully unique Buff Manager for this conditional group. Changes made to your default Buff Manager will no longer affect it."] = "Dies erstellt einen vollständig eigenständigen Stärkungszauber Manager für diese bedingte Gruppe. Änderungen an Deinem Standard-Stärkungszauber Manager wirken sich nicht mehr darauf aus."
L["This will create a fully unique Buff Manager for this override group. Changes made to your default Buff Manager will no longer affect these specs."] = "Dies erstellt einen vollständig eigenständigen Stärkungszauber Manager für diese Überschreibungsgruppe. Änderungen an Deinem Standard-Stärkungszauber Manager wirken sich nicht mehr auf diese Spezialisierungen aus."
L["This will create a fully unique Debuff Manager for this conditional group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect it."] = "Dies erstellt einen vollkommen eigenständigen Schwächungszauber Manager für diese bedingte Gruppe. Deine aktuellen Einstellungen werden als Startpunkt kopiert, und Änderungen an Deinem Standard-Schwächungszauber Manager wirken sich nicht mehr darauf aus."
L["This will create a fully unique Debuff Manager for this override group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect these specs."] = "Dies erstellt einen vollkommen eigenständigen Schwächungszauber Manager für diese Überschreibungsgruppe. Deine aktuellen Einstellungen werden als Startpunkt kopiert, und Änderungen an Deinem Standard-Schwächungszauber Manager wirken sich nicht mehr auf diese Spezialisierungen aus."
L["This will disable EllesmereUI Tracking Bars and show Blizzard's default Tracked Bars display instead."] = "Dies deaktiviert die EllesmereUI Überwachungsleisten und zeigt stattdessen die Blizzard-Standardleisten an."
L["This will discard your custom party settings for this section and use raid settings instead."] = "Dies verwirft Ihre eigenen Gruppeneinstellungen für diesen Bereich und nutzt stattdessen die Schlachtzugs Einstellungen."
L["This will display the word \"FOCUS\" below caster/miniboss mobs in M+ if you have not set your focus. Disabled for specs with no kick."] = "Zeigt das Wort 'FOKUS' unter Zauberern/Minibossen in M+ an, wenn Sie kein Fokus-Ziel gesetzt haben. Deaktiviert für Klassen ohne Unterbrechung."
L["This will not override sorting by role"] = "Dies überschreibt nicht die Sortierung nach Rolle"
L["This will not reset addon-specific Quick Setup."] = "Dies setzt die addon spezifische Schnelleinrichtung nicht zurück."
L["This will overwrite %1$s settings on the selected profiles with your current settings. Continue?"] = "Dies überschreibt die %1$s Einstellungen auf den gewählten Profilen mit Ihren aktuellen Einstellungen. Fortfahren?"
L["This will physically scatter items to random positions in your bags. The changes persist even if you disable EllesmereUI Bags."] = "Dies verteilt Gegenstände physisch auf zufällige Plätze in Ihren Taschen. Bleibt auch nach Deaktivierung von EllesmereUI Bags bestehen."
L["This will pin your bar to the window when it is not within the visible area"] = "Dies heftet Ihre Leiste am Fenster fest, wenn sie sich nicht im sichtbaren Bereich befindet"
L["This will reset all saved panel positions and reload your UI."] = "Dies setzt alle gespeicherten Fensterpositionen zurück und lädt das UI neu."
L["This will reset all saved panel positions and zoom levels and reload your UI."] = "Dies setzt alle gespeicherten Fensterpositionen sowie Zoomstufen zurück und lädt dein UI neu."
