L["Weekly and event choice windows such as Abundance harvests and \"how will you aid...\" pickers: option plates, headers, reward icons and buttons. Option artwork stays."] = "Wöchentliche und Ereignis-Auswahlfenster wie Fülle-Ernten und 'Wie wollt Ihr helfen...'-Auswahlen: Optionsflächen, Kopfzeilen, Belohnungssymbole und Schaltflächen. Optionsgrafiken bleiben erhalten."
