L["You can now color the gaps between class resource pips and set the color and opacity of the empty slot overlay."] = "Du kannst nun die Lücken zwischen den Klassenressourcen Anzeigen einfärben sowie Farbe und Deckkraft leerer Plätze bestimmen."
L["You can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing."] = "Du kannst alle Änderungen jederzeit rückgängig machen, indem Du auf 'Meine Einstellungen wiederherstellen' klickst."
L["You changed settings while profile sync is active. Please reload your UI for sync changes to take effect."] = "Du hast Einstellungen bei aktiver Profil Synchronisierung geändert. Bitte lade das UI neu, damit die Änderungen wirksam werden."
