L["You"] = "Du"
L["You're on this spec."] = "Du spielst derzeit diese Spezialisierung."
L["You've Got Mail!"] = "Du hast Post!"
L["Your chat position is now controlled by Blizzard Edit Mode.\nPlease adjust its position there."] = "Deine Chat Position wird jetzt durch den Blizzard Bearbeitungsmodus gesteuert. Bitte passe die Position dort an."
L["Your current spec has an assigned profile so you cannot switch to another. Please unassign to switch."] = "Ihrer aktuellen Spezialisierung ist ein Profil zugewiesen. Bitte heben Sie die Zuweisung auf, um zu wechseln."
L["Your current spec has its own custom Buff Manager, so conditional Buff Managers never apply to it."] = "Deine aktuelle Spezialisierung hat ihren eigenen benutzerdefinierten Stärkungszauber Manager, daher werden bedingte Stärkungszauber Manager niemals darauf angewendet."
L["Your current spec has its own custom Debuff Manager, so conditional Debuff Managers never apply to it."] = "Deine aktuelle Spezialisierung besitzt ihren eigenen Schwächungszauber Manager, daher finden bedingte Schwächungszauber Manager auf sie keine Anwendung."
L["Your current spec has its own custom unlock mode, so conditional unlock modes never apply to it. Swap to a spec without one to customize this."] = "Deine aktuelle Spezialisierung hat ihren eigenen benutzerdefinierten Freischaltmodus, daher werden bedingte Freischaltmodi niemals darauf angewendet. Wechsle zu einer Spezialisierung ohne benutzerdefinierten Modus, um dies anzupassen."
L["Your Edit Mode layout is a Blizzard preset which cannot be modified by addons. Please switch to a custom Edit Mode layout so EllesmereUI can manage your CDM settings.\n\nOpen Edit Mode to create or select a custom layout."] = "Dein Bearbeitungsmodus Layout ist eine Blizzard Vorlage, die nicht von Addons geändert werden kann. Bitte wechsle zu einem benutzerdefinierten Bearbeitungsmodus Layout, damit EllesmereUI Deine CDM Einstellungen verwalten kann.\n\nÖffne den Bearbeitungsmodus, um ein benutzerdefiniertes Layout zu erstellen oder auszuwählen."
L["Your game client language uses a system font automatically.\nFont selection is not available for this locale."] = "Die Sprache Deines Spiel-Clients nutzt automatisch eine Systemschriftart. Schriftartenauswahl ist für diese Sprache nicht verfügbar."
